import{_ as t,c as o,o as r,aj as n}from"./chunks/framework.DaB7tcLF.js";const _=JSON.parse('{"title":"World of Open Source Survey","description":"","frontmatter":{"title":"World of Open Source Survey","date":"2026-10-16","banner":"assets/blog/20261016_neonephos_world_of_open_source_survey_banner.svg","authors":["neonephos-team"],"tags":["2026","news"],"published":true},"headers":[],"relativePath":"20261016_world_of_open_source_survey.md","filePath":"20261016_world_of_open_source_survey.md"}'),a={name:"20261016_world_of_open_source_survey.md"};function s(i,e,l,h,p,d){return r(),o("div",null,e[0]||(e[0]=[n('<h1 id="world-of-open-source-europe-spotlight" tabindex="-1">World of Open Source Europe: Spotlight <a class="header-anchor" href="#world-of-open-source-europe-spotlight" aria-label="Permalink to &quot;World of Open Source Europe: Spotlight&quot;">​</a></h1><p>On October 7th during the Open Source Summit in Prague, the Linux Foundation released the results of the fifth annual <a href="https://www.linuxfoundation.org/research/world-of-open-source-eu-2026?hsLang=en" target="_blank" rel="noreferrer">State of Open Source in Europe survey</a>. For this year&#39;s edition, which the NeoNephos Foundation co-sponsored, the report grants the topic of digital sovereignty special attention.</p><h2 id="why-digital-sovereignty-matters" tabindex="-1">Why digital Sovereignty matters <a class="header-anchor" href="#why-digital-sovereignty-matters" aria-label="Permalink to &quot;Why digital Sovereignty matters&quot;">​</a></h2><p>The numbers could not be more stark: 94% of European respondents (n=264) rate <em>digital sovereignty</em> at least <em>somewhat important</em> to their organization, 61.5% even <em>very important</em> (<a href="https://zenodo.org/records/23083813" target="_blank" rel="noreferrer">Q18</a>). According to the survey, the main drivers behind this sentiment are <em>Security and privacy</em> (71%), <em>Vendor lock-in and cost risk</em> (55%) and <em>National or regional interests</em> (47%) (<a href="https://zenodo.org/records/23083813" target="_blank" rel="noreferrer">Q19</a>). An important takeaway is that this sentiment is shared across the world, as the data highlights similar results for respondents <em>outside</em> Europe. Anecdotically, we can attest to that as our visits to <a href="https://neonephos.org/events/2026_06_18_KubeCon_India" target="_blank" rel="noreferrer">KubeCon + CloudNativeCon India</a> and <a href="https://github.com/neonephos/events/issues/11" target="_blank" rel="noreferrer">KubeCon + CloudNativeCon Japan</a> showed great interest in our foundation from local companies and attendants.</p><p>Open source can help in this regard. But the data suggests that exploitation is linked to internal governance and governance of the open source project itself:</p><p>TODO:</p><p>Continue:</p><p><a href="https://www.linuxfoundation.org/hubfs/Research%20Reports/WorldofOS_EUSpotlight_2026_final.pdf?hsLang=en" target="_blank" rel="noreferrer">https://www.linuxfoundation.org/hubfs/Research%20Reports/WorldofOS_EUSpotlight_2026_final.pdf?hsLang=en</a><a href="https://zenodo.org/records/23083813" target="_blank" rel="noreferrer">https://zenodo.org/records/23083813</a></p><p>substanceThe general sent Open source and sovereignty are strongly</p>',9)]))}const c=t(a,[["render",s]]);export{_ as __pageData,c as default};
